findings.artefact_proposal:
[[artefact]]
id = "inspect.art.bundled_file_not_found"
title = "Bundled-content file tools fail with file not found"
description = "AgentHarm's read_file and convert_pdf_to_text resolve their bundled files relative to the working directory; the survey ran the benchmark from the inspect_evals checkout root, so these calls returned a file-not-found error (read_file) or result text (convert_pdf_to_text). Scores of the affected samples rest on a broken tool environment (inspect_evals #2439)."
scope = { sources = ["agent-security-tools-survey"], parts = ["agentharm"], profiles = ["survey-agentharm"] }
cause = "upstream_harness"
detector = { rule = "<new: inspect.file_tool_not_found@1, tool_execution status error with error type file_not_found, or env result marker 'File not found at'>", class = "O" }
recorded_as = {}
handling = { class = "FO" }
expected = [
  { snapshot = "git:89c4db2c949797fbb38c5bfed85dc82780ddbfe3", count = 63, basis = "samples with >= 1 failed call: coder_benign 13, coder_harmful 9, gptoss_benign 15, gptoss_harmful 2, qwen14_benign 12, qwen14_harmful 12; calls: read_file 84 of 93, convert_pdf_to_text 63 of 63, edit_txt 0 of 2" },
]
manuscript = true
refs = ["https://github.com/UKGovernmentBEIS/inspect_evals/issues/2439", "docs/reports/precheck/data/ast-survey-agentharm/raw-hypotheses.json"]
